import {validate,scriptKind,executableScript} from './core.js';
export function previewDocument(bundle, testing=false, expected='C2', nonce=''){
 validate(bundle);const kind=scriptKind(bundle['script.js']);const doc=new DOMParser().parseFromString(bundle['index.html'],'text/html');
 const allowed=new Set(['MAIN','DIV','SPAN','H1','H2','H3','P','BUTTON','SECTION','STRONG','EM','SMALL','BR']);
 for(const el of [...doc.body.querySelectorAll('*')]){if(!allowed.has(el.tagName)){el.remove();continue;}for(const attr of [...el.attributes])if(!['id','class','role','aria-live','aria-label','disabled'].includes(attr.name))el.removeAttribute(attr.name);}
 const css=bundle['style.css'].replace(/<\/style/gi,'');
 const js=executableScript(bundle['script.js']);
 const harness=testing?`const button2=document.querySelector('button#rsvp');const count2=document.querySelector('#count');const initialCount=Number(count2?.textContent);const status2=document.querySelector('#status');let checks=[{name:'Event title exists',pass:!!document.querySelector('h1')?.textContent.trim()}];if(${JSON.stringify(expected)}!=='C1'){button2?.click();checks.push({name:'RSVP registers once',pass:!!button2?.disabled&&button2?.textContent.includes("on the list")});checks.push({name:'Confirmation is announced',pass:!!status2?.textContent.includes('See you')&&status2?.getAttribute('aria-live')==='polite'});if(${JSON.stringify(expected)}==='C3'){button2?.click();checks.push({name:'Attendee count increments once',pass:Number.isFinite(initialCount)&&Number(count2?.textContent)===initialCount+1});}}checks.push({name:'Prepared script ran without errors',pass:runtimeErrors.length===0});parent.postMessage({type:'rejoin-check',nonce:${JSON.stringify(nonce)},checks},'*');`:'';
 return `<!doctype html><html><head><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'none'; connect-src 'none'; form-action 'none'; base-uri 'none'"><style>${css}</style></head><body>${doc.body.innerHTML}<script>const runtimeErrors=[];addEventListener('error',event=>{runtimeErrors.push('Prepared script error');event.preventDefault();});${js}\n${harness}<\/script></body></html>`;
}
export async function verify(bundle, expected){if(scriptKind(bundle['script.js'])==='unsupported')return {passed:false,message:'Not run: custom JavaScript is outside the restricted workshop runner.',checks:[]};
 return new Promise(resolve=>{const frame=document.createElement('iframe');frame.hidden=true;frame.sandbox='allow-scripts';const nonce=crypto.randomUUID();let timer;const done=result=>{clearTimeout(timer);window.removeEventListener('message',receive);frame.remove();resolve(result);};const receive=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='rejoin-check'||e.data?.nonce!==nonce)return;const checks=e.data.checks;const passed=checks.every(c=>c.pass);done({passed,checks,message:passed?`${expected}: ${checks.length}/${checks.length} prepared-workshop checks passed. Custom title and styles are not assessed for visual quality.`:checks.filter(c=>!c.pass).map(c=>c.name+': failed').join(' · ')});};window.addEventListener('message',receive);timer=setTimeout(()=>done({passed:false,message:'Checks timed out. Result is inconclusive.',checks:[]}),2500);frame.srcdoc=previewDocument(bundle,true,expected,nonce);document.body.append(frame);});}
